void Solver::bump_var(int var, double coeff) {
    // Guard against invalid variable indices
    if (var < 1 || var > vars) return;

    // Increase activity by the scaled increment
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale all activities if any exceeds a safe threshold to avoid overflow
    const double RESCALE_LIMIT = 1e120;
    const double RESCALE_FACTOR = 1e-120;
    if (activity[var] > RESCALE_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE_FACTOR;
        var_inc *= RESCALE_FACTOR;
    }

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
